import { readFile, writeFile } from 'node:fs/promises';
import { isDeepStrictEqual } from 'node:util';
import { librarySqlite } from '../lib/library-from-sql.mjs';
import { layoutRuntime } from '../lib/layout-runtime.mjs';

const defaultFile = (path) => new URL(path, import.meta.url);
const [
  input,
  output = defaultFile('../../bundled-footprints/starter-v1.tplib'),
] = process.argv.slice(2);
if (!input)
  throw new Error(
    'Pass the JSON manifest generated by generate-starter-footprints.py.',
  );

const [manifest, evidenceText, api, SQL] = await Promise.all([
  readFile(input, 'utf8'),
  readFile(defaultFile('./starter-footprint-evidence.json'), 'utf8'),
  layoutRuntime(),
  librarySqlite(),
]);
const { version, variants } = JSON.parse(manifest);
if (version !== 1) throw new Error('Unsupported footprint manifest.');
const { footprints, acceptance } = JSON.parse(evidenceText);
const records = new Map(footprints.map((record) => [record.id, record]));
if (records.size !== variants.length || records.size !== footprints.length)
  throw new Error('Every starter footprint needs one geometry review record.');

const devices = [];
for (const entry of variants) {
  const { id, footprint, documentation, bodyNm } = entry;
  const record = records.get(id);
  if (
    record?.digest !== footprint.definition.definitionDigest ||
    !record.basis.length
  )
    throw new Error(
      `Review evidence does not match the current ${id} footprint.`,
    );
  if (!record.device) continue;
  const { partNumber, pinout, mechanicalPads = [] } = record.device;
  if (
    partNumber !== documentation?.partNumber ||
    !isDeepStrictEqual(pinout, documentation.pinoutByPad) ||
    !isDeepStrictEqual(mechanicalPads, documentation.mechanicalPads ?? [])
  )
    throw new Error(`Reviewed terminal assignments do not match ${id}.`);

  const mappings = new Map(
    footprint.definition.pads.map(({ id: padId, label }) => [
      padId,
      mechanicalPads.includes(label)
        ? { kind: 'mechanical' }
        : { kind: 'signal', terminal: pinout[label] },
    ]),
  );
  const { license } = footprint.assets[0];
  const reviewEvidence = [
    acceptance,
    record.notes,
    `Terminal assignments for ${partNumber} verified against ${documentation.pinout}.`,
    `Package reference ${documentation.package}.`,
  ]
    .filter(Boolean)
    .join(' ');
  const bytes = await api.publishFootprintDevice(footprint, {
    widthNm: bodyNm[0],
    heightNm: bodyNm[1],
    packageName: partNumber,
    license,
    reviewer: 'TinyCAD starter catalogue verification',
    evidence: reviewEvidence,
    mappings,
  });
  const device = JSON.parse(new TextDecoder().decode(bytes));
  if (!isDeepStrictEqual(device.footprint, footprint.definition))
    throw new Error(`Publishing changed the reviewed ${id} footprint.`);
  devices.push({ id, device });
}
await api.readLibraryDeviceCatalogue({
  version: 1,
  devices: devices.map(({ device }) => device),
});

const db = new SQL.Database();
try {
  db.run(`
    PRAGMA foreign_keys = ON;
    PRAGMA user_version = 1;
    CREATE TABLE Model (id TEXT PRIMARY KEY, bytes BLOB NOT NULL) WITHOUT ROWID;
    CREATE TABLE Footprint (id TEXT PRIMARY KEY, entry TEXT NOT NULL) WITHOUT ROWID;
    CREATE TABLE Device (
      footprint_id TEXT PRIMARY KEY REFERENCES Footprint(id),
      definition TEXT NOT NULL
    ) WITHOUT ROWID;
    BEGIN;
  `);
  for (const entry of variants) {
    const { assets, ...footprint } = entry.footprint;
    for (const { id, base64 } of assets) {
      db.run('INSERT OR IGNORE INTO Model (id, bytes) VALUES (?, ?)', [
        id,
        Buffer.from(base64, 'base64'),
      ]);
    }
    db.run('INSERT INTO Footprint (id, entry) VALUES (?, ?)', [
      entry.id,
      JSON.stringify({
        ...entry,
        footprint: {
          ...footprint,
          assets: assets.map(({ base64, ...asset }) => asset),
        },
      }),
    ]);
  }
  for (const { id, device } of devices) {
    const { footprint, models, ...definition } = device;
    db.run('INSERT INTO Device (footprint_id, definition) VALUES (?, ?)', [
      id,
      JSON.stringify(definition),
    ]);
  }
  db.run('COMMIT;');
  await writeFile(output, db.export());
} finally {
  db.close();
}
console.log(
  `Packaged ${variants.length} footprints and ${devices.length} mapped devices.`,
);
